const saida = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const chave of Object.keys(bin)) {
    const b = bin[chave];
    const nome = String(b.fileName || '').toLowerCase();
    const mime = String(b.mimeType || '').toLowerCase();
    const ehPdf = mime.indexOf('pdf') !== -1 || nome.slice(-4) === '.pdf';
    if (!ehPdf) continue;
    saida.push({
      json: {
        arquivo: b.fileName || chave,
        email_id: item.json.id || null,
        assunto: item.json.subject || null,
        recebido_em: item.json.date || null
      },
      binary: { data: b }
    });
  }
}
return saida;

const PRIORIDADE = ['proprietario', 'responsavel', 'comprador', 'engenheiro', 'construtor', 'empreiteiro', 'arquiteto', 'pedreiro'];
const ANY_LABEL = '(?:Cidade|Cliente|Contatos?|Obra|M[2\u00b2]|Est[a\u00e1]gio|In[i\u00ed]cio|T[e\u00e9]rmino|Endere[c\u00e7]o|Observa[c\u00e7][a\u00e3]o|Filtros)\\s*:';

function semAcento(s) {
  return String(s === null || s === undefined ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function limpar(s) {
  return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim();
}
function cortarNoProximoLabel(s) {
  return limpar(String(s).split(new RegExp(ANY_LABEL, 'i'))[0]);
}
function campo(bloco, label) {
  const re = new RegExp(label + '\\s*:\\s*([\\s\\S]*?)(?=' + ANY_LABEL + '|$)', 'i');
  const m = bloco.match(re);
  return m ? limpar(m[1]) : '';
}
function classificarNumero(bruto) {
  const d = String(bruto).replace(/\D/g, '');
  if (d.length === 9 && d.charAt(0) === '9') return { numero: d, celular: true };
  if (d.length === 8) {
    if (Number(d.charAt(0)) >= 6) return { numero: '9' + d, celular: true };
    return { numero: d, celular: false };
  }
  return null;
}
function extrairContatos(str) {
  const lista = [];
  const re = /\((\d{2})\)\s*(\d[\d\s.\-]{6,13})(?:\s*\(([^)]*)\))?/g;
  let m = re.exec(str);
  while (m !== null) {
    const meta = limpar(m[3] || '');
    let nomeContato = meta;
    let papel = '';
    const sep = meta.lastIndexOf(' - ');
    if (sep !== -1) {
      nomeContato = limpar(meta.slice(0, sep));
      papel = limpar(meta.slice(sep + 3));
    } else if (meta.indexOf('-') !== -1) {
      const partes = meta.split('-');
      papel = limpar(partes.pop());
      nomeContato = limpar(partes.join('-'));
    }
    const cls = classificarNumero(m[2]);
    lista.push({
      ddd: m[1],
      bruto: limpar(m[2]),
      numero: cls ? cls.numero : '',
      celular: cls ? cls.celular : false,
      valido: cls !== null,
      nome_contato: nomeContato,
      papel: papel
    });
    m = re.exec(str);
  }
  return lista;
}
function porPrioridade(contatos, obs) {
  const obsN = semAcento(obs);
  for (const c of contatos) {
    const primeiro = semAcento(c.nome_contato).split(' ')[0];
    if (primeiro && primeiro.length >= 4 && obsN.indexOf(primeiro) !== -1) return c;
  }
  for (const p of PRIORIDADE) {
    if (obsN.indexOf(p) !== -1) {
      const achado = contatos.filter(function (c) { return semAcento(c.papel).indexOf(p) !== -1; })[0];
      if (achado) return achado;
    }
  }
  for (const p of PRIORIDADE) {
    const achado = contatos.filter(function (c) { return semAcento(c.papel).indexOf(p) !== -1; })[0];
    if (achado) return achado;
  }
  return contatos[0];
}

const leads = [];
const avisos = [];

for (const item of $input.all()) {
  const arquivo = item.json.arquivo || 'desconhecido';
  const texto = String(item.json.text || '');
  const ehRelatorio = /Relat[o\u00f3]rio\s+CRM/i.test(texto);
  const temFiltro = /Filtros\s*:[\s\S]{0,60}?Regi[a\u00e3]o\s*:/i.test(texto);
  if (!ehRelatorio || !temFiltro) {
    avisos.push({ tipo: 'pdf_ignorado', arquivo: arquivo, motivo: 'nao contem "Relatorio CRM" e "Filtros: Regiao:"' });
    continue;
  }

  const mReg = texto.match(/Regi[a\u00e3]o\s*:\s*([^\n\r]*)/i);
  const regiao = mReg ? limpar(cortarNoProximoLabel(mReg[1]).replace(/\s+\S+\s*:.*$/, '')) : '';

  const iCidade = texto.search(/Cidade\s*:/i);
  const iCliente = texto.search(/Cliente\s*:/i);
  let ancora = 'Cidade';
  if (iCliente !== -1 && (iCidade === -1 || iCliente < iCidade)) ancora = 'Cliente';
  const blocos = texto.split(new RegExp('(?=' + ancora + '\\s*:)', 'i'));

  let cidadeAtual = '';
  for (const bloco of blocos) {
    const cidade = campo(bloco, 'Cidade');
    if (cidade) cidadeAtual = cidade;
    const nome = campo(bloco, 'Cliente');
    const contatoRaw = campo(bloco, 'Contatos?');
    if (!nome && !contatoRaw) continue;

    const idObra = campo(bloco, 'Obra');
    const metragem = campo(bloco, 'M[2\u00b2]');
    const fase = campo(bloco, 'Est[a\u00e1]gio');
    const inicio = campo(bloco, 'In[i\u00ed]cio');
    const termino = campo(bloco, 'T[e\u00e9]rmino');
    const endereco = campo(bloco, 'Endere[c\u00e7]o');
    const obs = campo(bloco, 'Observa[c\u00e7][a\u00e3]o');

    const contatos = extrairContatos(contatoRaw);
    if (!contatos.length) {
      avisos.push({ tipo: 'sem_contato', arquivo: arquivo, obra: idObra, nome: nome, cidade: cidadeAtual });
      continue;
    }
    const invalidos = contatos.filter(function (c) { return !c.valido; });
    if (invalidos.length) {
      avisos.push({ tipo: 'telefone_invalido', arquivo: arquivo, obra: idObra, nome: nome, numeros: invalidos.map(function (c) { return '(' + c.ddd + ') ' + c.bruto; }) });
    }

    const celulares = contatos.filter(function (c) { return c.valido && c.celular; });
    const universo = celulares.length ? celulares : contatos.filter(function (c) { return c.valido; });
    if (!universo.length) {
      avisos.push({ tipo: 'nenhum_telefone_valido', arquivo: arquivo, obra: idObra, nome: nome });
      continue;
    }
    const alvo = porPrioridade(universo, obs);
    const semCelular = !alvo.celular;
    if (semCelular) {
      avisos.push({ tipo: 'sem_celular', arquivo: arquivo, obra: idObra, nome: nome, telefone: '(' + alvo.ddd + ') ' + alvo.bruto, papel: alvo.papel });
    }

    leads.push({
      json: {
        id_obra: idObra,
        nome: alvo.nome_contato || nome,
        nome_cliente: nome,
        ddd: alvo.ddd,
        numero: alvo.numero,
        papel: alvo.papel,
        nome_contato: alvo.nome_contato,
        cidade: cidadeAtual,
        regiao: regiao,
        metragem: metragem,
        fase: fase,
        inicio: inicio,
        termino: termino,
        endereco: endereco,
        obs: obs,
        sem_celular: semCelular,
        contatos_no_bloco: contatos.length,
        arquivo: arquivo
      }
    });
  }
}

if (avisos.length) console.log('avisos de parse: ' + JSON.stringify(avisos));
return leads;

function limpar(s) {
  return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim();
}
function normalizarTelefone(ddd, numero) {
  const d = String(ddd || '').replace(/\D/g, '');
  let n = String(numero || '').replace(/\D/g, '');
  if (n.length === 8 && Number(n.charAt(0)) >= 6) n = '9' + n;
  if (d.length !== 2 || Number(d) < 11 || Number(d) > 99) return null;
  if (n.length !== 8 && n.length !== 9) return null;
  return '55' + d + n;
}
function mesesDesde(mmAAAA) {
  const m = String(mmAAAA || '').match(/(\d{1,2})\s*[\/\-.]\s*(\d{4})/);
  if (!m) return null;
  const mes = Number(m[1]);
  const ano = Number(m[2]);
  if (!mes || !ano || mes < 1 || mes > 12) return null;
  const agora = $now.setZone('America/Sao_Paulo');
  return (agora.year - ano) * 12 + (agora.month - mes);
}

const porTelefone = {};
const invalidos = [];

for (const item of $input.all()) {
  const l = item.json;
  const telefone = normalizarTelefone(l.ddd, l.numero);
  if (!telefone) {
    invalidos.push({ tipo: 'telefone_nao_normalizado', nome: l.nome, ddd: l.ddd, numero: l.numero, obra: l.id_obra, arquivo: l.arquivo });
    continue;
  }
  const meses = mesesDesde(l.inicio);
  const decadencia = meses !== null && meses > 60;
  const obra = {
    id_obra: l.id_obra,
    endereco: l.endereco,
    fase: l.fase,
    metragem: l.metragem,
    inicio: l.inicio,
    termino: l.termino,
    possivel_decadencia: decadencia
  };
  if (!porTelefone[telefone]) {
    porTelefone[telefone] = {
      telefone: telefone,
      nome: limpar(l.nome),
      nome_cliente: limpar(l.nome_cliente),
      papel: limpar(l.papel),
      cidade: limpar(l.cidade),
      regiao: limpar(l.regiao),
      obras: [obra],
      multi_obra: false,
      metragem: l.metragem,
      inicio: l.inicio,
      termino: l.termino,
      obs: limpar(l.obs),
      sem_celular: !!l.sem_celular,
      possivel_decadencia: decadencia,
      arquivos: [l.arquivo]
    };
  } else {
    const alvo = porTelefone[telefone];
    const jaTem = alvo.obras.filter(function (o) { return o.id_obra === obra.id_obra; }).length > 0;
    if (!jaTem) alvo.obras.push(obra);
    alvo.multi_obra = alvo.obras.length > 1;
    alvo.possivel_decadencia = alvo.possivel_decadencia || decadencia;
    if (alvo.arquivos.indexOf(l.arquivo) === -1) alvo.arquivos.push(l.arquivo);
    if (!alvo.obs && l.obs) alvo.obs = limpar(l.obs);
  }
}

const saida = Object.keys(porTelefone).map(function (t) {
  const lead = porTelefone[t];
  lead.multi_obra = lead.obras.length > 1;
  return { json: lead };
});

if (invalidos.length) console.log('telefones invalidos: ' + JSON.stringify(invalidos));
saida.push({ json: { __log: true, tipo: 'resumo_parse', total_leads: saida.length, telefones_invalidos: invalidos } });
return saida;

function q(v) {
  if (v === null || v === undefined || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function b(v) {
  return v ? 'true' : 'false';
}

const entrada = $('Tratar, Deduplicar Lote e Sinalizar').all().map(function (i) { return i.json; });
const leads = entrada.filter(function (l) { return !l.__log; });
const logs = entrada.filter(function (l) { return l.__log; });

const existentes = {};
for (const linha of $('Buscar Leads Existentes').all()) {
  if (linha.json && linha.json.telefone) existentes[linha.json.telefone] = linha.json.status;
}

const saida = [];
const pulados = [];

for (const lead of leads) {
  const statusAtual = existentes[lead.telefone];
  if (statusAtual && statusAtual !== 'erro') {
    pulados.push({ telefone: lead.telefone, status: statusAtual });
    continue;
  }
  const status = lead.sem_celular ? 'erro' : 'novo';
  const sql = 'insert into disparo.leads (telefone, nome, nome_cliente, papel, cidade, regiao, obras, multi_obra, metragem, inicio, termino, obs, possivel_decadencia, sem_celular, status, origem) values ('
    + q(lead.telefone) + ', ' + q(lead.nome) + ', ' + q(lead.nome_cliente) + ', ' + q(lead.papel) + ', ' + q(lead.cidade) + ', ' + q(lead.regiao) + ', '
    + q(JSON.stringify(lead.obras || [])) + '::jsonb, ' + b(lead.multi_obra) + ', ' + q(lead.metragem) + ', '
    + q(lead.inicio) + ', ' + q(lead.termino) + ', ' + q(lead.obs) + ', ' + b(lead.possivel_decadencia) + ', '
    + b(lead.sem_celular) + ', ' + q(status) + ", 'guia_da_construcao') "
    + 'on conflict (telefone) do update set '
    + 'nome = coalesce(excluded.nome, disparo.leads.nome), '
    + 'nome_cliente = coalesce(excluded.nome_cliente, disparo.leads.nome_cliente), '
    + 'papel = coalesce(excluded.papel, disparo.leads.papel), '
    + 'cidade = coalesce(excluded.cidade, disparo.leads.cidade), '
    + 'regiao = coalesce(excluded.regiao, disparo.leads.regiao), '
    + 'obras = excluded.obras, multi_obra = excluded.multi_obra, '
    + 'metragem = coalesce(excluded.metragem, disparo.leads.metragem), '
    + 'inicio = coalesce(excluded.inicio, disparo.leads.inicio), '
    + 'termino = coalesce(excluded.termino, disparo.leads.termino), '
    + 'obs = coalesce(excluded.obs, disparo.leads.obs), '
    + 'possivel_decadencia = excluded.possivel_decadencia, sem_celular = excluded.sem_celular, '
    + "status = case when disparo.leads.status = 'erro' and excluded.sem_celular = false then 'novo' else disparo.leads.status end, "
    + 'atualizado_em = now() returning telefone, status;';
  saida.push({ json: { telefone: lead.telefone, nome: lead.nome, status: status, sql: sql } });
}

const resumo = {
  leads_no_lote: leads.length,
  gravados: saida.length,
  pulados_ja_existentes: pulados.length,
  detalhe_pulados: pulados.slice(0, 50),
  parse: logs
};
saida.push({
  json: {
    telefone: null,
    nome: 'log',
    status: 'log',
    sql: 'insert into disparo.log_ingestao (tipo, detalhe) values (' + q('ingestao_email') + ', ' + q(JSON.stringify(resumo)) + '::jsonb) returning id;'
  }
});
return saida;

const linha = $input.first().json;
const cfg = linha.config || {};
function num(chave, padrao) {
  const v = Number(cfg[chave]);
  return isNaN(v) ? padrao : v;
}
const TEST_MODE = String(cfg.TEST_MODE || 'true').toLowerCase() === 'true';
const NUMERO_TESTE = String(cfg.NUMERO_TESTE || '5565999725622').replace(/\D/g, '');
const MAX_HORA = num('MAX_HORA', 15);
const MAX_DIA_INICIAL = num('MAX_DIA_INICIAL', 20);
const MAX_DIA_INCREMENTO = num('MAX_DIA_INCREMENTO', 15);
const MAX_DIA_TETO = num('MAX_DIA_TETO', 90);
const DELAY_MIN_S = num('DELAY_MIN_S', 30);
const DELAY_MAX_S = num('DELAY_MAX_S', 90);
const JANELA_INICIO = num('JANELA_INICIO', 9);
const JANELA_FIM = num('JANELA_FIM', 19);
const LOTE_MAX = num('LOTE_MAX_EXECUCAO', 8);

const agora = $now.setZone('America/Sao_Paulo');
const hora = agora.hour;
if (hora < JANELA_INICIO || hora >= JANELA_FIM) {
  console.log('fora da janela de disparo (' + hora + 'h SP)');
  return [];
}

let diasDeAquecimento = 0;
if (linha.primeiro_dia) {
  const inicio = String(linha.primeiro_dia).slice(0, 10).split('-');
  const d0 = Date.UTC(Number(inicio[0]), Number(inicio[1]) - 1, Number(inicio[2]));
  const hoje = Date.UTC(agora.year, agora.month - 1, agora.day);
  diasDeAquecimento = Math.max(0, Math.round((hoje - d0) / 86400000));
}
const MAX_DIA = Math.min(MAX_DIA_INICIAL + MAX_DIA_INCREMENTO * diasDeAquecimento, MAX_DIA_TETO);

const restaHora = MAX_HORA - Number(linha.enviados_hora || 0);
const restaDia = MAX_DIA - Number(linha.enviados_hoje || 0);
const disponivel = Math.max(0, Math.min(restaHora, restaDia, LOTE_MAX));
const fila = Array.isArray(linha.leads) ? linha.leads : [];
if (disponivel <= 0 || !fila.length) {
  console.log('nada a enviar. disponivel=' + disponivel + ' fila=' + fila.length + ' max_dia=' + MAX_DIA);
  return [];
}

function saudacao(h) {
  if (h < 12) return 'Bom dia';
  if (h < 18) return 'Boa tarde';
  return 'Boa noite';
}
function primeiroNome(nome) {
  const partes = String(nome || '').trim().split(/\s+/);
  const bruto = partes[0] || '';
  return bruto.charAt(0).toUpperCase() + bruto.slice(1).toLowerCase();
}
function ruaCurta(endereco) {
  let e = String(endereco || '').split(',')[0];
  e = e.replace(/\s+n?[o\u00ba\u00b0]?\.?\s*\d+.*$/i, '');
  e = e.replace(/\s*-\s*.*$/, '');
  return e.trim();
}
function referenciaCurta(lead) {
  const obras = Array.isArray(lead.obras) ? lead.obras : [];
  const multi = lead.multi_obra || obras.length > 1;
  if (multi) return '';
  const rua = ruaCurta(obras.length ? obras[0].endereco : '');
  return rua || String(lead.cidade || '').trim();
}

const TEMPLATES = [
  function (s, n) { return s + ', ' + n + '! Aqui é a Ana, da equipe da WM Assessoria. Um parceiro nosso esteve na obra e me passou seu contato. Rapidinho: o INSS dessa obra já foi regularizado ou ainda tá pendente?'; },
  function (s, n) { return s + ', ' + n + ', tudo bem? Ana aqui, da WM Assessoria. A gente cuida da regularização do INSS de obras aqui na região. Passando pra saber: já resolveu essa parte da sua obra ou ainda não?'; },
  function (s, n, r) { return s + ', ' + n + '! É a Ana, da WM Assessoria. Um parceiro que passou na obra me deixou seu contato. Você já cuidou do INSS da obra (' + r + ') ou ainda tá em aberto?'; },
  function (s, n) { return s + ', ' + n + ', aqui é a Ana da WM Assessoria. Trabalhamos com redução do INSS de obras. Sua obra já foi regularizada na Receita ou ainda não chegou nessa etapa?'; },
  function (s, n, r) { return s + ', ' + n + '! Ana, da WM Assessoria. Vi que sua obra (' + r + ') tá em andamento. Já pensou na regularização do INSS dela? Muita gente deixa pro fim e acaba pagando mais.'; }
];
const SEM_REFERENCIA = [0, 1, 3];
const COM_REFERENCIA = [0, 1, 2, 3, 4];

const totalOut = Number(linha.total_out || 0);
const semNome = [];
const selecionados = fila.filter(function (l) {
  const temNome = String(l.nome || '').trim().length >= 2;
  if (!temNome) semNome.push(l.telefone);
  return temNome;
}).slice(0, disponivel);
if (semNome.length) console.log('leads sem nome, nao enviados: ' + JSON.stringify(semNome));
const saida = [];

for (let i = 0; i < selecionados.length; i++) {
  const lead = selecionados[i];
  const ref = referenciaCurta(lead);
  const elegiveis = ref ? COM_REFERENCIA : SEM_REFERENCIA;
  const idx = elegiveis[(totalOut + i) % elegiveis.length];
  const mensagemLead = TEMPLATES[idx](saudacao(hora), primeiroNome(lead.nome), ref);
  const telefoneReal = String(lead.telefone).replace(/\D/g, '');
  let telefoneEnvio = telefoneReal;
  let mensagemEnvio = mensagemLead;
  if (TEST_MODE) {
    telefoneEnvio = NUMERO_TESTE;
    mensagemEnvio = '[TESTE | lead: ' + (lead.nome || '') + ' | tel real: ' + telefoneReal + ' | ' + (lead.cidade || '') + '/' + (lead.regiao || '') + ']\n' + mensagemLead;
  }
  saida.push({
    json: {
      telefone: telefoneReal,
      telefone_envio: telefoneEnvio,
      mensagem_lead: mensagemLead,
      mensagem_envio: mensagemEnvio,
      template_idx: idx,
      delay_s: Math.floor(Math.random() * (DELAY_MAX_S - DELAY_MIN_S + 1)) + DELAY_MIN_S,
      nome: lead.nome,
      cidade: lead.cidade,
      regiao: lead.regiao,
      test_mode: TEST_MODE,
      max_dia: MAX_DIA,
      posicao: i + 1,
      total_lote: selecionados.length
    }
  });
}
return saida;

const enviados = $input.all().map(function (i) { return i.json; });
const ok = enviados.filter(function (e) { return e.status_envio === 'enviado'; }).length;
return [{
  json: {
    executado_em: $now.setZone('America/Sao_Paulo').toISO(),
    total_tentativas: enviados.length,
    enviados: ok,
    erros: enviados.length - ok
  }
}];

function q(v) {
  if (v === null || v === undefined || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const contexto = $('Aguardar Intervalo Aleatorio').all()[0].json;
const resposta = $input.first().json || {};
const codigo = Number(resposta.statusCode || 0);
const corpo = resposta.body === undefined ? resposta : resposta.body;
const ok = codigo >= 200 && codigo < 300 && !(corpo && corpo.error);
const status = ok ? 'enviado' : 'erro';
const telefone = q(contexto.telefone);

const registroMensagem = 'insert into disparo.mensagens (telefone, template_idx, direcao, conteudo, status) values ('
  + telefone + ', ' + Number(contexto.template_idx || 0) + ", 'out', " + q(contexto.mensagem_lead) + ', ' + q(status) + ') returning 1';

let atualizaLead;
if (ok) {
  atualizaLead = 'update disparo.leads set status = ' + q('enviado')
    + ', template_idx = ' + Number(contexto.template_idx || 0)
    + ', primeiro_contato = coalesce(primeiro_contato, now()), ultimo_contato = now(), atualizado_em = now() where telefone = ' + telefone + ' returning 1';
} else {
  atualizaLead = 'update disparo.leads set status = case when (select count(*) from disparo.mensagens where telefone = ' + telefone
    + " and direcao = 'out' and status = 'erro') >= 2 then 'erro' else 'novo' end"
    + ', ultimo_contato = now(), atualizado_em = now() where telefone = ' + telefone + ' returning 1';
}

const sql = 'with m as (' + registroMensagem + '), u as (' + atualizaLead + ') select ' + q(status) + ' as status_envio, ' + telefone + ' as telefone;';

return [{
  json: {
    telefone: contexto.telefone,
    telefone_envio: contexto.telefone_envio,
    nome: contexto.nome,
    template_idx: contexto.template_idx,
    status_envio: status,
    http_status: codigo,
    resposta_zapi: corpo,
    sql: sql
  }
}];
